<?php use VO\Support\Template; $navUser = (isset($user) && is_array($user)) ? $user : null; $nav = $navUser !== null ? \VO\Admin\AdminNav::entries((int)$navUser['id']) : []; ?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><?php if (!empty($autoRefresh)): ?><meta http-equiv="refresh" content="30"><?php endif; ?><title><?= Template::e($title ?? 'Panel de administración') ?></title><link rel="stylesheet" href="/admin/assets/admin.css"></head><body><?php if ($nav && $navUser !== null): ?><input type="checkbox" id="nav-toggle" class="nav-toggle"><header class="topbar"><label class="burger" for="nav-toggle" aria-label="Menú"><span></span><span></span><span></span></label><span class="topbar-name"><?= Template::e($navUser['business_name'] ?? '') ?></span></header><div class="admin-shell"><aside class="sidebar"><p class="brand"><?= Template::e($navUser['business_name'] ?? '') ?></p><nav><?php foreach ($nav as $item): ?><a href="<?= Template::e($item['href']) ?>"<?= $item['active'] ? ' class="active"' : '' ?>><?= Template::e($item['label']) ?></a><?php endforeach; ?></nav><?php if (\VO\Admin\AdminNav::allows((int)$navUser['id'], 'products.manage')): ?><form class="jump" method="get" action="/admin/pedidos"><label for="nav-jump-q">Ir a pedido</label><input id="nav-jump-q" name="q" placeholder="N° de pedido" maxlength="32" autocomplete="off"></form><?php endif; ?><form class="logout" method="post" action="/admin/logout"><input type="hidden" name="csrf" value="<?= Template::e($csrf ?? '') ?>"><button class="btn secondary">Cerrar sesión</button></form></aside><main class="shell"><?= $content ?></main></div><?php else: ?><main class="shell"><?= $content ?></main><?php endif; ?></body></html>
